$slug=trim($_GET['product']??$_POST['product_slug']??'');$product=null;$errors=[];$success=null;$spamSuccess=false;$values=$_POST;$questionnaire=null;$requiresQuestionnaire=false;
if($slug!==''&&table_exists(db(),'products')){$select='p.*,ct.title contract_title,ct.version contract_version,ct.body contract_body,ct.status contract_template_status';if(table_exists(db(),'questionnaire_templates'))$select.=',qt.status questionnaire_template_status';else $select.=',NULL questionnaire_template_status';$sql="SELECT $select FROM products p LEFT JOIN contract_templates ct ON p.contract_template_id=ct.id ".(table_exists(db(),'questionnaire_templates')?'LEFT JOIN questionnaire_templates qt ON p.questionnaire_template_id=qt.id ':'')."WHERE p.slug=? AND p.status='active'";$s=db()->prepare($sql);$s->execute([$slug]);$product=$s->fetch();}
if($product){$requiresQuestionnaire=questionnaire_requires_assignment($product['intake_type']??'general_service');$questionnaire=load_product_questionnaire(db(),$product,true);if($questionnaire&&questionnaire_definition_errors($questionnaire['fields']))$questionnaire=null;}
if($_SERVER['REQUEST_METHOD']==='POST'&&$product){verify_csrf();if(trim($_POST['website_url_confirm']??'')!==''){$spamSuccess=true;$values=[];}else{$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$url=trim($_POST['website_url']??'');$answers=[];$questionnaireUploads=[];
 if($name==='')$errors[]='First and last name is required.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='A valid email address is required.';if($url!==''&&!valid_url_or_blank($url))$errors[]='Website/platform URL must be a valid HTTP or HTTPS link.';
 if($requiresQuestionnaire){if(!$questionnaire)$errors[]='This service is temporarily unavailable while its questionnaire is assigned.';else{[$qErrors,$answers,$questionnaireUploads]=validate_questionnaire_submission($questionnaire,$_POST,$_FILES);$errors=array_merge($errors,$qErrors);$url=(string)($answers['shopify_store_url']??$answers['current_shopify_store_url']??$url);}}
 if(!$product['contract_template_id']||$product['contract_template_status']!=='active')$errors[]='This service is temporarily unavailable while its contract is assigned.';
 if(!$errors){$pdo=db();$token=create_contract_token();$orderNumber='';$written=[];try{$pdo->beginTransaction();$summary=$questionnaire?build_intake_summary(array_map(fn($v)=>is_array($v)?implode(', ',$v):(string)$v,$answers)):trim($_POST['project_notes']??'');$snapshot=['name'=>$product['name'],'price'=>$product['price'],'service_type'=>$product['service_type'],'intake_type'=>$product['intake_type']??'general_service','questionnaire_template_id'=>$product['questionnaire_template_id']??null,'contract_template_id'=>$product['contract_template_id'],'contract_title'=>$product['contract_title'],'contract_version'=>$product['contract_version'],'demo_url'=>$product['demo_url']??null];
 $pdo->prepare('INSERT INTO orders(product_id,customer_name,customer_email,business_name,phone,preferred_contact_method,website_url,project_notes,product_name_snapshot,product_price_snapshot,service_type_snapshot,product_snapshot_json,intake_answers_json,customer_ip,customer_user_agent,order_status,payment_status,contract_status,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())')->execute([(int)$product['id'],$name,$email,trim($_POST['business_name']??'')?:null,trim($_POST['phone']??'')?:null,trim($_POST['preferred_contact_method']??'')?:null,$url?:null,$summary?:null,$product['name'],$product['price'],$product['service_type'],json_encode($snapshot,JSON_THROW_ON_ERROR),$questionnaire?json_encode($answers,JSON_THROW_ON_ERROR):null,substr($_SERVER['REMOTE_ADDR']??'',0,100),substr($_SERVER['HTTP_USER_AGENT']??'',0,500),'pending_contract','pending','pending']);$orderId=(int)$pdo->lastInsertId();$orderNumber=order_number($orderId);$pdo->prepare('UPDATE orders SET order_number=? WHERE id=?')->execute([$orderNumber,$orderId]);
 if($questionnaire){$snap=questionnaire_snapshot($questionnaire);$pdo->prepare('INSERT INTO order_questionnaire_snapshots(order_id,questionnaire_template_id,questionnaire_title,questionnaire_snapshot_json,created_at) VALUES (?,?,?,?,NOW())')->execute([$orderId,(int)$questionnaire['id'],$questionnaire['title'],json_encode($snap,JSON_THROW_ON_ERROR)]);$snapId=(int)$pdo->lastInsertId();foreach($questionnaire['fields'] as $field){if(in_array($field['field_type'],QUESTIONNAIRE_STRUCTURAL_TYPES,true))continue;$answer=$answers[$field['field_key']]??($field['field_type']==='checkboxes'?[]:'');$json=is_array($answer)?json_encode($answer,JSON_THROW_ON_ERROR):null;$text=is_array($answer)?null:(string)$answer;$pdo->prepare('INSERT INTO order_questionnaire_answers(order_id,questionnaire_snapshot_id,field_key,field_type,question_label,answer_text,answer_json,sort_order,created_at) VALUES (?,?,?,?,?,?,?,?,NOW())')->execute([$orderId,$snapId,$field['field_key'],$field['field_type'],$field['label'],$text,$json,(int)$field['sort_order']]);$answerId=(int)$pdo->lastInsertId();foreach($questionnaireUploads[$field['field_key']]??[] as $file){[$asset,$uploadError]=upload_order_asset($file);if($uploadError)throw new RuntimeException($uploadError);if($asset){$written[]=$asset['path'];$pdo->prepare('INSERT INTO order_uploads(order_id,file_path,original_name,mime_type,file_size,upload_type,questionnaire_field_key,questionnaire_answer_id,created_at) VALUES (?,?,?,?,?,?,?,?,NOW())')->execute([$orderId,$asset['path'],$asset['original_name'],$asset['mime_type'],$asset['file_size'],'questionnaire',$field['field_key'],$answerId]);}}}}
 $contractAnswers=[];foreach($answers as $k=>$v)$contractAnswers[$k]=is_array($v)?implode(', ',$v):$v;$placeholderData=array_merge($contractAnswers,['client_name'=>$name,'client_email'=>$email,'business_name'=>trim($_POST['business_name']??''),'order_id'=>$orderNumber,'product_name'=>$product['name'],'product_price'=>money_format_dd($product['price']),'service_type'=>service_type_label($product['service_type']),'project_url'=>$url,'order_date'=>date('Y-m-d'),'designer_name'=>'Diesel Designs','site_name'=>'Diesel Designs','intake_summary'=>$summary]);$rendered=render_contract_template($product['contract_body'],$placeholderData);$pdo->prepare('INSERT INTO contract_instances(order_id,contract_template_id,contract_title_snapshot,contract_version_snapshot,contract_body_snapshot,rendered_contract_snapshot,token_hash,status,created_at) VALUES (?,?,?,?,?,?,?,\'pending\',NOW())')->execute([$orderId,$product['contract_template_id'],$product['contract_title'],$product['contract_version'],$product['contract_body'],$rendered,token_hash($token)]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();foreach($written as $path){$full=__DIR__.'/'.$path;if(is_file($full))@unlink($full);}$errors[]=$e instanceof RuntimeException?$e->getMessage():'We could not start this order. Please try again or contact Diesel Designs.';}
 if(!$errors){$signingUrl=base_url_from_request().'/sign-contract.php?token='.$token;notify_admin_order_created(['order_number'=>$orderNumber,'customer_name'=>$name,'customer_email'=>$email,'product_name'=>$product['name']],$signingUrl);$success=['order'=>$orderNumber,'token'=>$token];$values=[];}}}}
function q_value(array $values,string $key,mixed $default=''):mixed{$answers=is_array($values['q']??null)?$values['q']:[];return $answers[$key]??$default;}
$pageTitle='Begin Purchase | Diesel Designs';$metaDescription='Start a Diesel Designs service order and receive a secure contract signing link.';include __DIR__.'/includes/header.php';?>
<section class="page-hero purchase-page-hero"><h1>Purchase / Start Order</h1><?php if($product):?><p><?=e($product['name'])?> · <?=e(money_format_dd($product['price']))?></p><?php endif;?></section><section class="section purchase-section">
<?php if(!$product):?><div class="empty"><h2>Service not available</h2><p>Please choose an active service from the store.</p><a class="btn" href="store.php">Back to Store</a></div><?php elseif(!$product['contract_template_id']||$product['contract_template_status']!=='active'||($requiresQuestionnaire&&!$questionnaire)):?><div class="empty"><h2>Temporarily unavailable</h2><p>This service needs an active contract<?= $requiresQuestionnaire?' and questionnaire':''?> assigned before public purchase.</p></div><?php elseif($spamSuccess):?><div class="empty success-message"><h2>Thanks, your request was received.</h2></div><?php elseif($success):?><div class="empty success-message"><h2>Order started</h2><p>Your order <?=e($success['order'])?> was created. Please sign the contract before work begins.</p><a class="btn btn-accent" href="sign-contract.php?token=<?=e($success['token'])?>">Sign Contract</a></div><?php else:?><?php foreach($errors as $error):?><p class="error-text"><?=e($error)?></p><?php endforeach;?>
<form method="post" enctype="multipart/form-data" class="admin-form request-form"><?=csrf_field()?><input type="hidden" name="product_slug" value="<?=e($slug)?>"><label class="honeypot" aria-hidden="true">Leave blank<input name="website_url_confirm" tabindex="-1"></label><label>First &amp; Last name *<input name="name" autocomplete="name" maxlength="190" required value="<?=e($values['name']??'')?>"></label><label>What is your email address? *<small>We may need to contact you for questions or follow-ups.</small><input type="email" name="email" autocomplete="email" maxlength="190" required value="<?=e($values['email']??'')?>"></label>
<?php if($questionnaire):?><h2><?=e($questionnaire['title'])?></h2><?php foreach($questionnaire['fields'] as $field):?><?php $key=$field['field_key'];$type=$field['field_type'];$required=!empty($field['is_required']);$helpId='help-'.$key;?><?php if($type==='section_heading'):?><h3 class="questionnaire-section-heading"><?=e($field['label'])?></h3><?php elseif($type==='information'):?><p class="notice"><?=nl2br(e($field['label']))?></p><?php else:?><fieldset class="questionnaire-field"><legend><?=e($field['label'])?><?=$required?' *':''?></legend><?php if($field['help_text']):?><small id="<?=$helpId?>"><?=nl2br(e($field['help_text']))?></small><?php endif;?>
<?php $attrs=($required?' required':'').($field['help_text']?' aria-describedby="'.$helpId.'"':'');$placeholder=$field['placeholder']?' placeholder="'.e($field['placeholder']).'"':'';?>
<?php if($type==='long_text'):?><textarea name="q[<?=e($key)?>]"<?=$attrs.$placeholder?>><?=e((string)q_value($values,$key))?></textarea><?php elseif(in_array($type,['short_text','email','phone','url','number','date'],true)):?><?php $htmlType=['short_text'=>'text','phone'=>'tel'][$type]??$type;?><input type="<?=e($htmlType)?>" name="q[<?=e($key)?>]" value="<?=e((string)q_value($values,$key))?>"<?=$attrs.$placeholder?>><?php elseif($type==='yes_no'):?><?php foreach(['yes'=>'Yes','no'=>'No'] as $v=>$label):?><label><input type="radio" name="q[<?=e($key)?>]" value="<?=$v?>" <?=q_value($values,$key)===$v?'checked':''?><?=$required?' required':''?>> <?=e($label)?></label><?php endforeach;?><?php elseif($type==='dropdown'):?><select name="q[<?=e($key)?>]"<?=$attrs?>><option value="">Choose one</option><?php foreach($field['options'] as $option):?><option value="<?=e($option)?>" <?=q_value($values,$key)===$option?'selected':''?>><?=e($option)?></option><?php endforeach;?></select><?php elseif($type==='radio'):?><?php foreach($field['options'] as $option):?><label><input type="radio" name="q[<?=e($key)?>]" value="<?=e($option)?>" <?=q_value($values,$key)===$option?'checked':''?><?=$required?' required':''?>> <?=e($option)?></label><?php endforeach;?><?php elseif($type==='checkboxes'):?><?php $selected=(array)q_value($values,$key,[]);foreach($field['options'] as $option):?><label><input type="checkbox" name="q[<?=e($key)?>][]" value="<?=e($option)?>" <?=in_array($option,$selected,true)?'checked':''?>> <?=e($option)?></label><?php endforeach;?><?php elseif(in_array($type,QUESTIONNAIRE_FILE_TYPES,true)):?><input type="file" name="q_<?=e($key)?><?=$type==='multiple_files'?'[]':''?>" accept="<?=e(implode(',',array_map(fn($x)=>'.'.$x,$field['validation']['allowed_extensions']??['png','jpg','jpeg','webp','pdf'])))?>" <?=$type==='multiple_files'?'multiple':''?><?=$required?' required':''?>><?php endif;?></fieldset><?php endif;?><?php endforeach;?>
<?php else:?><label>Website/platform URL<input type="url" name="website_url" maxlength="500" value="<?=e($values['website_url']??'')?>"></label><label>Project notes/details<textarea name="project_notes"><?=e($values['project_notes']??'')?></textarea></label><?php endif;?><button class="btn btn-accent">Begin Purchase</button></form><?php endif;?></section><?php include __DIR__.'/includes/footer.php';?>
